// Landing data (PRD 0023): use cases, FAQ items and the app captures they show.
import type { Lang } from "../../i18n";
import { ROUTES } from "../../routes";

export const FAQ_ID = "faq";
export const FAQ_HREF = `/#${FAQ_ID}`;

/** Real app captures, one set per language, generated by `npm run shots:landing`. */
export type ShotName =
  | "hero-card-1" | "hero-card-2" | "hero-card-3"
  | "game-1" | "game-2" | "catch-evolve-before" | "catch-evolve-after" | "catch-pick"
  | "catch-map-list" | "catch-map" | "catch-settings" | "catch-card-base" | "catch-card-rival"
  | "share-dialog" | "share-copied" | "share-preview"
  | "plan-card-1" | "plan-card-2" | "plan-card-3" | "plan-card-4" | "plan-card-5"
  | "plan-fav-1" | "plan-fav-2" | "plan-fav-3" | "plan-fav-4" | "plan-fav-5"
  | "plan-map-list" | "plan-map" | "plan-cooking" | "plan-totals"
  | "levelup-entry-1" | "levelup-tip-1" | "levelup-entry-2" | "levelup-tip-2";

export function shotUrl(name: ShotName, lang: Lang): string {
  return `/landing/${lang}/${name}.jpg`;
}

export type UseCaseId = "catch" | "share" | "plan" | "levelup";

/** The catch tile's story, step by step; copy keys: landing.catch.step.<id>. */
/** The plan tile's story: build the team, pick the map, check the meals, see the week. */
export type PlanStepId = "team" | "map" | "meals" | "week";
export const PLAN_STEPS: readonly PlanStepId[] = ["team", "map", "meals", "week"];

export type CatchStepId = "upload" | "evolve" | "pick" | "settings" | "compare";
export const CATCH_STEPS: readonly { id: CatchStepId; shots: readonly ShotName[] }[] = [
  { id: "upload", shots: ["game-1", "game-2"] },
  // Before and after: the form's species and level, Tyrunt then Tyrantrum.
  { id: "evolve", shots: ["catch-evolve-before", "catch-evolve-after"] },
  { id: "pick", shots: ["catch-pick"] },
  // The open map list walked down to Taupe Hollow, then the dialog and bar with it and level 60 set.
  { id: "settings", shots: ["catch-map-list", "catch-map", "catch-settings"] },
  // Each card alone, so the newcomer can push the rival aside.
  { id: "compare", shots: ["catch-card-rival", "catch-card-base"] },
];

export interface UseCase {
  id: UseCaseId;
  to: string;
  needsAccount: boolean;
  linkKey: string;
}

// Copy keys derive from the id: landing.case.<id>.title / .body / .alt
export const USE_CASES: readonly UseCase[] = [
  { id: "catch", to: ROUTES.compare, needsAccount: true, linkKey: "landing.go.compare" },
  { id: "share", to: ROUTES.compare, needsAccount: false, linkKey: "landing.go.compare" },
  { id: "plan", to: ROUTES.teamAnalysis, needsAccount: false, linkKey: "landing.go.teamAnalysis" },
  { id: "levelup", to: ROUTES.box, needsAccount: true, linkKey: "landing.go.box" },
];

/** What works without an account and what one adds; copy keys: landing.access.row.<id>. */
